by_assignee_stats.map:
function (doc) {
  if(doc.type == 'issue' && doc.confirmed) {
    let assignee = 0;
    if (doc.assignee) {
      assignee = doc.assignee.id;
    }
    emit(assignee, 1);
  }
}

group_by_assignee.map:
function (doc) {
  if(doc.type == 'issue' && doc.confirmed && doc.status.name != 'Closed' && doc.assignee && doc.category) {
    emit([doc.category.assigned_department, doc.assignee.id, doc.assignee.name]);
  }
}

by_type_and_user.map:
function(doc) { 
  if (doc.type === 'issue') { 
    if (doc.reporter && doc.reporter.id) {
      emit([doc.type, doc.reporter.id], null);
    }
    if (doc.assignee && doc.assignee.id) {
      emit([doc.type, doc.assignee.id], null);
    }
  }
}

by_type_and_id.map:
function(doc) { 
  if (doc.type && doc.id) {
    emit([doc.type, doc.id], doc.name);
  }
}

all_issue_types.map:
function(doc) { 
  const issueTypes = ['issue_status', 'issue_age_group', 'issue_citizen_group_1', 'issue_citizen_group_2', 'issue_category', 'issue_type', 'issue_component', 'issue_sub_component', 'issue_sub_type'];
  if (issueTypes.includes(doc.type)) {
    emit([doc.type, doc._id], null);
  }
}
